[CmdletBinding(SupportsShouldProcess)] param([Parameter(Mandatory)][string]$CsvPath,[Parameter(Mandatory)][securestring]$TemporaryPassword)
Import-Module ActiveDirectory; $rows=Import-Csv $CsvPath
foreach($r in $rows){if(Get-ADUser -Filter "SamAccountName -eq '$($r.SamAccountName)'" -ErrorAction SilentlyContinue){Write-Warning "Skipped $($r.SamAccountName): exists"; continue}; $ou="OU=$($r.Department -replace ' ','-'),OU=CTS-Users,DC=cts-lab,DC=local"; if($PSCmdlet.ShouldProcess($r.SamAccountName,'Create imported user')){New-ADUser -Name "$($r.FirstName) $($r.LastName)" -GivenName $r.FirstName -Surname $r.LastName -SamAccountName $r.SamAccountName -UserPrincipalName $r.UPN -Department $r.Department -Title $r.Title -Path $ou -AccountPassword $TemporaryPassword -Enabled $true -ChangePasswordAtLogon $true}}
